#include <stdio.h>
#include <stdlib.h>
#include "libexif/exif-data.h"
#include "libexif/exif-loader.h"

int main(int argc, char** argv) {
    ExifLoader *loader = exif_loader_new();
    exif_loader_write_file(loader, argv[1]);
    ExifData *d = exif_loader_get_data(loader);
    if (!d) { printf("no data\n"); return 1; }
    ExifEntry *e = exif_data_get_entry(d, EXIF_TAG_MAKER_NOTE);
    if (!e) { printf("no maker note entry\n"); return 1; }
    printf("maker note size=%u data:", e->size);
    for (unsigned i=0;i<e->size;i++) printf(" %02x", e->data[i]);
    printf("\n");
    return 0;
}
EOF
